90	static int EepromWriteByte(uint16_t memAddr, uint8_t data)
91	{
92	    uint8_t buf[3] = {
93	        (uint8_t)(memAddr >> 8),
94	        (uint8_t)(memAddr & 0xFF),
95	        data,
96	    };
97	
98	    return IoTI2cWrite(EEPROM_I2C_ID, EEPROM_I2C_ADDR, buf, sizeof(buf));
99	}
100	
101	static int EepromReadByte(uint16_t memAddr, uint8_t *data)
102	{
103	    uint8_t addr[2] = {
104	        (uint8_t)(memAddr >> 8),
105	        (uint8_t)(memAddr & 0xFF),
106	    };
107	    int ret;
108	
109	    ret = IoTI2cWrite(EEPROM_I2C_ID, EEPROM_I2C_ADDR, addr, sizeof(addr));
110	    if (ret != 0) {
111	        return ret;
112	    }
113	
114	    return IoTI2cRead(EEPROM_I2C_ID, EEPROM_I2C_ADDR, data, 1);
115	}
