122	    ls_pinmux_pin_setup(I2C1_SDA_PIN, LS_PINMUX_MODE_AS_MAIN_FUNC);
123	
124	    ret = IoTI2cInit(EEPROM_I2C_ID, EEPROM_I2C_BAUDRATE);
125	    printf("[EEPROM] IoTI2cInit ret=%d\r\n", ret);
126	    if (ret != 0) {
127	        return ret;
128	    }
129	
130	    printf("[EEPROM] addr=0x%02x, SCL GPIO%d, SDA GPIO%d\r\n",
