135	static int EepromSaveMode(LedMode mode)
136	{
137	    uint8_t verifyMagic = 0;
138	    uint8_t verifyMode = 0;
139	    uint8_t verifyCheck = 0;
140	    int ret;
141	
142	    ret = EepromWriteByte(EEPROM_MODE_ADDR, (uint8_t)mode);
143	    if (ret != 0) {
144	        printf("[EEPROM] save mode failed ret=%d\r\n", ret);
145	        return ret;
146	    }
147	    osDelay(EEPROM_WRITE_DELAY);
148	
149	    ret = EepromWriteByte(EEPROM_CHECK_ADDR, EepromModeCheck(mode));
150	    if (ret != 0) {
151	        printf("[EEPROM] save check failed ret=%d\r\n", ret);
152	        return ret;
153	    }
154	    osDelay(EEPROM_WRITE_DELAY);
155	
156	    ret = EepromWriteByte(EEPROM_MAGIC_ADDR, EEPROM_MAGIC_VALUE);
157	    if (ret != 0) {
158	        printf("[EEPROM] save magic failed ret=%d\r\n", ret);
159	        return ret;
160	    }
161	    osDelay(EEPROM_WRITE_DELAY);
162	
163	    ret = EepromReadByte(EEPROM_MAGIC_ADDR, &verifyMagic);
164	    if (ret != 0) {
165	        printf("[EEPROM] verify magic read failed ret=%d\r\n", ret);
166	        return ret;
167	    }
168	
169	    ret = EepromReadByte(EEPROM_MODE_ADDR, &verifyMode);
170	    if (ret != 0) {
171	        printf("[EEPROM] verify mode read failed ret=%d\r\n", ret);
172	        return ret;
173	    }
174	
175	    ret = EepromReadByte(EEPROM_CHECK_ADDR, &verifyCheck);
176	    if (ret != 0) {
177	        printf("[EEPROM] verify check read failed ret=%d\r\n", ret);
178	        return ret;
179	    }
180	
181	    if (verifyMagic != EEPROM_MAGIC_VALUE || verifyMode != (uint8_t)mode ||
182	        verifyCheck != EepromModeCheck(mode)) {
183	        printf("[EEPROM] verify failed: magic=0x%02x mode=0x%02x check=0x%02x\r\n",
184	            verifyMagic, verifyMode, verifyCheck);
185	        return -1;
186	    }
187	
188	    printf("[EEPROM] saved and verified LED mode: %s\r\n", g_ledModeName[mode]);
189	    return 0;
190	}
