192	static LedMode EepromLoadMode(void)
193	{
194	    uint8_t mode = 0;
195	    uint8_t magic = 0;
196	    uint8_t check = 0;
197	    int ret;
198	
199	    ret = EepromReadByte(EEPROM_MAGIC_ADDR, &magic);
200	    if (ret != 0) {
201	        printf("[EEPROM] read magic failed ret=%d, use default red\r\n", ret);
202	        return LED_MODE_RED;
203	    }
204	
205	    ret = EepromReadByte(EEPROM_MODE_ADDR, &mode);
206	    if (ret != 0) {
207	        printf("[EEPROM] read mode failed ret=%d, use default red\r\n", ret);
208	        return LED_MODE_RED;
209	    }
210	
211	    ret = EepromReadByte(EEPROM_CHECK_ADDR, &check);
212	    if (ret != 0) {
213	        printf("[EEPROM] read check failed ret=%d, use default red\r\n", ret);
214	        return LED_MODE_RED;
215	    }
216	
217	    if (magic != EEPROM_MAGIC_VALUE || mode >= LED_MODE_MAX ||
218	        check != EepromModeCheck((LedMode)mode)) {
219	        printf("[EEPROM] no valid saved mode: magic=0x%02x mode=0x%02x check=0x%02x, use default red\r\n",
220	            magic, mode, check);
221	        return LED_MODE_RED;
222	    }
223	
224	    printf("[EEPROM] loaded LED mode: %s\r\n", g_ledModeName[mode]);
225	    return (LedMode)mode;
226	}
227	
228	static LedMode LedModeNext(LedMode mode)
229	{
230	    return (LedMode)(((unsigned int)mode + 1U) % LED_MODE_MAX);
231	}
232	
233	static LedMode LedModePrev(LedMode mode)
234	{
235	    if (mode == LED_MODE_RED) {
236	        return LED_MODE_OFF;
237	    }
238	    return (LedMode)((unsigned int)mode - 1U);
239	}
