241	static void LoongHatEepromTask(void *arg)
242	{
243	    LedMode mode;
244	    int key1Last = 0;
245	    int key2Last = 0;
246	
247	    (void)arg;
248	
249	    printf("[LOONG-HAT] EEPROM LED mode demo start\r\n");
250	    printf("[LOONG-HAT] RGB pins: red GPIO%d, green GPIO%d, blue GPIO%d\r\n",
251	        LOONG_HAT_LED_RED, LOONG_HAT_LED_GREEN, LOONG_HAT_LED_BLUE);
252	    printf("[LOONG-HAT] KEY1 GPIO%d next color, KEY2 GPIO%d previous color\r\n",
253	        LOONG_HAT_KEY1, LOONG_HAT_KEY2);
254	
255	    LedInit(LOONG_HAT_LED_RED);
256	    LedInit(LOONG_HAT_LED_GREEN);
257	    LedInit(LOONG_HAT_LED_BLUE);
258	    KeyInit(LOONG_HAT_KEY1);
259	    KeyInit(LOONG_HAT_KEY2);
260	
261	    while (EepromInit() != 0) {
262	        osDelay(1000);
263	    }
264	
265	    mode = EepromLoadMode();
266	    LedApplyMode(mode);
267	
268	    while (1) {
269	        int key1Now = KeyPressed(LOONG_HAT_KEY1);
270	        int key2Now = KeyPressed(LOONG_HAT_KEY2);
271	
272	        if (key1Now && !key1Last) {
273	            osDelay(KEY_DEBOUNCE_DELAY);
274	            if (KeyPressed(LOONG_HAT_KEY1)) {
275	                mode = LedModeNext(mode);
276	                LedApplyMode(mode);
277	                printf("[KEY] KEY1 pressed, LED mode: %s\r\n", g_ledModeName[mode]);
278	                (void)EepromSaveMode(mode);
279	            }
280	        }
281	
282	        if (key2Now && !key2Last) {
283	            osDelay(KEY_DEBOUNCE_DELAY);
284	            if (KeyPressed(LOONG_HAT_KEY2)) {
285	                mode = LedModePrev(mode);
286	                LedApplyMode(mode);
287	                printf("[KEY] KEY2 pressed, LED mode: %s\r\n", g_ledModeName[mode]);
288	                (void)EepromSaveMode(mode);
289	            }
290	        }
291	
292	        key1Last = key1Now;
293	        key2Last = key2Now;
294	        osDelay(KEY_SCAN_DELAY);
295	    }
296	}
