129	static bool get_key_value(int fd)
130	{
131	  bool value = true;
132	
133	  ioctl(fd, GPIOC_READ, (unsigned long)(uintptr_t)&value);
134	  return value;
135	}
136	
137	static int is_key_pressed(key_state_s *key)
138	{
139	  bool value = get_key_value(key->fd);
140	
141	  /* Detect falling edge: HIGH -> LOW = press */
142	
143	  if (!value && key->last_value)
144	    {
145	      up_mdelay(KEY_DEBOUNCE_MS);
146	      value = get_key_value(key->fd);
147	      if (!value)
148	        {
149	          key->last_value = value;
150	          return 1;
151	        }
152	    }
153	
154	  key->last_value = value;
155	  return 0;
156	}
157	
158	static void set_led(int fd, int on)
159	{
160	  /* Active-low: 0 = ON, 1 = OFF */
161	
162	  ioctl(fd, GPIOC_WRITE, on ? 0 : 1);
163	}
