169	int test_key(void)
170	{
171	  int fd_red;
172	  int fd_blue;
173	  int fd_green;
174	  int fd_key1;
175	  int fd_key2;
176	  key_state_s key1;
177	  key_state_s key2;
178	  int red_on = 0;
179	  int green_on = 0;
180	  int blue_on = 0;
181	  unsigned int blue_tick = 0;
182	  unsigned int total_tick = 0;
183	
184	  printf("[KEY] === Key + LED Test (loong_hat 02_KEY) ===\n");
185	  printf("[KEY] KEY1(GPIO%d) -> toggle red LED(GPIO%d)\n",
186	         KEY1_GPIO, LED_RED_GPIO);
187	  printf("[KEY] KEY2(GPIO%d) -> toggle green LED(GPIO%d)\n",
188	         KEY2_GPIO, LED_GREEN_GPIO);
189	  printf("[KEY] Blue LED(GPIO%d) blinks every %dms\n",
190	         LED_BLUE_GPIO, BLUE_BLINK_INTERVAL_MS);
191	  printf("[KEY] Test duration: %d seconds\n\n",
192	         KEY_TEST_DURATION_MS / 1000);
193	
194	  /* Initialize LEDs */
195	
196	  fd_red = init_led_gpio(LED_RED_GPIO);
197	  if (fd_red < 0)
198	    {
199	      return fd_red;
200	    }
201	
202	  fd_blue = init_led_gpio(LED_BLUE_GPIO);
203	  if (fd_blue < 0)
204	    {
205	      close(fd_red);
206	      return fd_blue;
207	    }
208	
209	  fd_green = init_led_gpio(LED_GREEN_GPIO);
210	  if (fd_green < 0)
211	    {
212	      close(fd_red);
213	      close(fd_blue);
214	      return fd_green;
215	    }
216	
217	  /* Initialize keys */
218	
219	  fd_key1 = init_key_gpio(KEY1_GPIO);
220	  if (fd_key1 < 0)
221	    {
222	      close(fd_red);
223	      close(fd_blue);
224	      close(fd_green);
225	      return fd_key1;
226	    }
227	
228	  fd_key2 = init_key_gpio(KEY2_GPIO);
229	  if (fd_key2 < 0)
230	    {
231	      close(fd_red);
232	      close(fd_blue);
233	      close(fd_green);
234	      close(fd_key1);
235	      return fd_key2;
236	    }
237	
238	  /* Read initial key states */
239	
240	  key1.fd = fd_key1;
241	  key1.last_value = get_key_value(fd_key1);
242	  key2.fd = fd_key2;
243	  key2.last_value = get_key_value(fd_key2);
244	
245	  printf("[KEY] Initial: KEY1=%s KEY2=%s\n",
246	         key1.last_value ? "HIGH" : "LOW",
247	         key2.last_value ? "HIGH" : "LOW");
248	  printf("[KEY] Ready. Press keys to test...\n\n");
249	
250	  /* Main loop - scan keys, blink blue LED */
251	
252	  while (total_tick < KEY_TEST_DURATION_MS)
253	    {
254	      /* Check KEY1 - toggle red LED */
255	
256	      if (is_key_pressed(&key1))
257	        {
258	          red_on = !red_on;
259	          set_led(fd_red, red_on);
260	          printf("[KEY] KEY1 pressed, red %s\n",
261	                 red_on ? "ON" : "OFF");
262	        }
263	
264	      /* Check KEY2 - toggle green LED */
265	
266	      if (is_key_pressed(&key2))
267	        {
268	          green_on = !green_on;
269	          set_led(fd_green, green_on);
270	          printf("[KEY] KEY2 pressed, green %s\n",
271	                 green_on ? "ON" : "OFF");
272	        }
273	
274	      /* Blink blue LED */
275	
276	      blue_tick += KEY_SCAN_DELAY_MS;
277	      if (blue_tick >= BLUE_BLINK_INTERVAL_MS)
278	        {
279	          blue_tick = 0;
280	          blue_on = !blue_on;
281	          set_led(fd_blue, blue_on);
282	        }
283	
284	      up_mdelay(KEY_SCAN_DELAY_MS);
285	      total_tick += KEY_SCAN_DELAY_MS;
286	    }
287	
288	  /* Turn off all LEDs */
289	
290	  set_led(fd_red, 0);
291	  set_led(fd_green, 0);
292	  set_led(fd_blue, 0);
293	
294	  printf("\n[KEY] Test complete. All LEDs off.\n");
295	
296	  close(fd_key2);
297	  close(fd_key1);
298	  close(fd_green);
299	  close(fd_blue);
300	  close(fd_red);
301	
302	  return OK;
303	}
