11	#define BH1750_I2C_ID   1
12	#define BH1750_ADDR_LOW  0x23
13	#define BH1750_ADDR_HIGH 0x5c
14	
15	#define I2C1_SCL_PIN    50
16	#define I2C1_SDA_PIN    51
17	
18	#define BH1750_POWER_ON 0x01
19	#define BH1750_RESET    0x07
20	#define BH1750_H_MODE   0x10
21	
22	static uint8_t g_bh1750Addr = BH1750_ADDR_LOW;
23	
24	static int BH1750_WriteCmd(uint8_t cmd)
25	{
26	    uint8_t data = cmd;
27	
28	    return IoTI2cWrite(BH1750_I2C_ID, g_bh1750Addr, &data, 1);
29	}
30	
31	static int BH1750_ReadData(uint8_t *buf, unsigned int len)
32	{
33	    return IoTI2cRead(BH1750_I2C_ID, g_bh1750Addr, buf, len);
34	}
