36	static int BH1750_ProbeAddr(uint8_t addr)
37	{
38	    g_bh1750Addr = addr;
39	    return BH1750_WriteCmd(BH1750_POWER_ON);
40	}
41	
42	static int BH1750_Init(void)
43	{
44	    int ret;
45	
46	    ls_pinmux_pin_setup(I2C1_SCL_PIN, LS_PINMUX_MODE_AS_MAIN_FUNC);
47	    ls_pinmux_pin_setup(I2C1_SDA_PIN, LS_PINMUX_MODE_AS_MAIN_FUNC);
48	
49	    ret = IoTI2cInit(BH1750_I2C_ID, 100000);
50	    printf("[BH1750] IoTI2cInit ret=%d\r\n", ret);
51	
52	    ret = BH1750_ProbeAddr(BH1750_ADDR_LOW);
53	    if (ret != 0) {
54	        printf("[BH1750] probe addr 0x%02x failed ret=%d\r\n", BH1750_ADDR_LOW, ret);
55	        ret = BH1750_ProbeAddr(BH1750_ADDR_HIGH);
56	    }
57	    if (ret != 0) {
58	        printf("[BH1750] probe addr 0x%02x failed ret=%d\r\n", BH1750_ADDR_HIGH, ret);
59	        printf("[BH1750] no ACK, check VCC/GND/SCL50/SDA51/ADDR pin\r\n");
60	        return ret;
61	    }
62	
63	    printf("[BH1750] detected addr=0x%02x\r\n", g_bh1750Addr);
64	    osDelay(2);
65	
66	    ret = BH1750_WriteCmd(BH1750_RESET);
67	    printf("[BH1750] reset ret=%d\r\n", ret);
68	    if (ret != 0) {
69	        return ret;
70	    }
71	    osDelay(2);
72	
73	    ret = BH1750_WriteCmd(BH1750_H_MODE);
74	    printf("[BH1750] h-mode ret=%d\r\n", ret);
75	    if (ret != 0) {
76	        return ret;
77	    }
78	    osDelay(180);
79	
80	    return 0;
81	}
82	
83	static int BH1750_ReadLuxX100(unsigned int *luxX100)
84	{
85	    uint8_t buf[2] = {0};
86	    int ret;
87	    unsigned int raw;
88	
89	    ret = BH1750_ReadData(buf, 2);
90	    if (ret != 0) {
91	        printf("[BH1750] read failed ret=%d\r\n", ret);
92	        return ret;
93	    }
94	
95	    raw = ((unsigned int)buf[0] << 8) | buf[1];
96	    *luxX100 = (raw * 1000 + 6) / 12;
97	
98	    return 0;
99	}
100	
101	static void BH1750_Task(void *arg)
102	{
103	    (void)arg;
104	
105	    printf("[LOONG-HAT] BH1750 demo start\r\n");
106	
107	    while (1) {
108	        unsigned int luxX100 = 0;
109	
110	        while (BH1750_Init() != 0) {
111	            osDelay(1000);
112	        }
113	
114	        while (BH1750_ReadLuxX100(&luxX100) == 0) {
115	            printf("[BH1750] light = %u.%02u lux\r\n", luxX100 / 100, luxX100 % 100);
116	
117	            if (luxX100 < 1000) {
118	                printf("[BH1750] environment: dark\r\n");
119	            } else {
120	                printf("[BH1750] environment: bright\r\n");
121	            }
122	
123	            osDelay(1000);
124	        }
125	
126	        printf("[BH1750] read failed, reinit sensor\r\n");
127	    }
128	}
129	
130	static void BH1750_Entry(void)
131	{
132	    osThreadAttr_t attr;
133	
134	    printf("[LOONG-HAT] BH1750 entry\r\n");
135	
136	    attr.name = "BH1750Task";
137	    attr.attr_bits = 0U;
138	    attr.cb_mem = NULL;
139	    attr.cb_size = 0U;
140	    attr.stack_mem = NULL;
141	    attr.stack_size = TASK_STACK_SIZE;
142	    attr.priority = TASK_PRIORITY;
143	
144	    if (osThreadNew(BH1750_Task, NULL, &attr) == NULL) {
145	        printf("[LOONG-HAT] create BH1750 task failed\r\n");
146	    }
147	}
148	
149	SYS_RUN(BH1750_Entry);
