81	static int sensor_i2c_write(uint8_t addr, const uint8_t *data, int len)
82	{
83	  struct i2c_msg_s msg;
84	  struct i2c_transfer_s trans;
85	
86	  msg.frequency = I2C_FREQ;
87	  msg.addr      = addr;
88	  msg.flags     = 0;
89	  msg.buffer    = (FAR uint8_t *)data;
90	  msg.length    = len;
91	
92	  trans.msgv = &msg;
93	  trans.msgc = 1;
94	
95	  return ioctl(g_i2c_fd, I2CIOC_TRANSFER, (unsigned long)&trans);
96	}
97	
98	static int sensor_i2c_read(uint8_t addr, uint8_t *data, int len)
99	{
100	  struct i2c_msg_s msg;
101	  struct i2c_transfer_s trans;
102	
103	  msg.frequency = I2C_FREQ;
104	  msg.addr      = addr;
105	  msg.flags     = I2C_M_READ;
106	  msg.buffer    = data;
107	  msg.length    = len;
108	
109	  trans.msgv = &msg;
110	  trans.msgc = 1;
111	
112	  return ioctl(g_i2c_fd, I2CIOC_TRANSFER, (unsigned long)&trans);
113	}
