124	static int bh1750_init(void)
125	{
126	  int ret;
127	
128	  /* Try low address first */
129	
130	  g_bh1750_addr = BH1750_ADDR_LOW;
131	  ret = bh1750_write_cmd(BH1750_POWER_ON);
132	  if (ret < 0)
133	    {
134	      printf("[BH1750] probe addr 0x%02x failed\n", BH1750_ADDR_LOW);
135	      g_bh1750_addr = BH1750_ADDR_HIGH;
136	      ret = bh1750_write_cmd(BH1750_POWER_ON);
137	    }
138	
139	  if (ret < 0)
140	    {
141	      printf("[BH1750] probe addr 0x%02x failed\n", BH1750_ADDR_HIGH);
142	      printf("[BH1750] no ACK, check wiring\n");
143	      return ret;
144	    }
145	
146	  printf("[BH1750] detected addr=0x%02x\n", g_bh1750_addr);
147	  usleep(20000);
148	
149	  ret = bh1750_write_cmd(BH1750_RESET);
150	  if (ret < 0)
151	    {
152	      printf("[BH1750] reset failed\n");
153	      return ret;
154	    }
155	  usleep(20000);
156	
157	  ret = bh1750_write_cmd(BH1750_H_MODE);
158	  if (ret < 0)
159	    {
160	      printf("[BH1750] set H-mode failed\n");
161	      return ret;
162	    }
163	  usleep(180000);
164	
165	  printf("[BH1750] init OK\n");
166	  return OK;
167	}
