259	static void oled_show_char(uint8_t x, uint8_t y, char ch, oled_font_e font)
260	{
261	  uint8_t c;
262	  uint8_t i;
263	
264	  if (ch < ' ' || ch > '~')
265	    {
266	      ch = ' ';
267	    }
268	
269	  c = (uint8_t)(ch - ' ');
270	
271	  if (font == FONT8X16)
272	    {
273	      oled_set_position(x, y);
274	      for (i = 0; i < 8; i++)
275	        {
276	          oled_write_data(F8X16[c * 16 + i]);
277	        }
278	
279	      oled_set_position(x, y + 1);
280	      for (i = 0; i < 8; i++)
281	        {
282	          oled_write_data(F8X16[c * 16 + 8 + i]);
283	        }
284	    }
285	  else
286	    {
287	      oled_set_position(x, y);
288	      for (i = 0; i < 6; i++)
289	        {
290	          oled_write_data(F6x8[c][i]);
291	        }
292	    }
293	}
