299	
300	  if (str == NULL)
301	    {
302	      return;
303	    }
304	
305	  while (*str != '\0')
306	    {
307	      oled_show_char(x, y, *str, font);
308	      x += step;
309	      if (x > (OLED_WIDTH - step))
310	        {
311	          x = 0;
312	          y += (font == FONT8X16) ? 2 : 1;
313	          if (y >= OLED_PAGES)
314	            {
315	              break;
316	            }
317	        }
318	
319	      str++;
320	    }
321	}
