346	
347	int test_sensor_oled(void)
348	{
349	  unsigned int lux_x100 = 0;
350	  int bh1750_ok = 0;
351	  int oled_ok = 0;
352	  int ret;
353	  int loop_count = 0;
354	
355	  printf("[SENSOR] === BH1750 + OLED Test ===\n");
356	  printf("[SENSOR] I2C1: SCL=GPIO50 SDA=GPIO51\n");
357	  printf("[SENSOR] Devices: BH1750(0x23/0x5C) OLED(0x3C)\n\n");
358	
359	  /* Open I2C1 */
360	
361	  printf("[SENSOR] Opening %s...\n", I2C1_PATH);
362	  g_i2c_fd = open(I2C1_PATH, O_RDWR);
363	  if (g_i2c_fd < 0)
364	    {
365	      printf("[SENSOR] ERROR: open %s failed: errno=%d\n",
366	             I2C1_PATH, errno);
367	      return -errno;
368	    }
369	
370	  printf("[SENSOR] I2C1 opened, fd=%d\n\n", g_i2c_fd);
371	
372	  /* Initialize BH1750 */
373	
374	  printf("[SENSOR] Init BH1750...\n");
375	  ret = bh1750_init();
376	  if (ret < 0)
377	    {
378	      printf("[SENSOR] BH1750 init FAILED (will skip light readings)\n\n");
379	    }
380	  else
381	    {
382	      bh1750_ok = 1;
383	    }
384	
385	  /* Initialize OLED */
386	
387	  printf("[SENSOR] Init OLED...\n");
388	  ret = oled_init_device();
389	  if (ret < 0)
390	    {
391	      printf("[SENSOR] OLED init FAILED\n");
392	      close(g_i2c_fd);
393	      return ret;
394	    }
395	  oled_ok = 1;
396	
397	  /* Show initial screen */
398	
399	  oled_fill_screen(0x00);
400	  oled_show_string(16, 0, "Loong Hat", FONT8X16);
401	  oled_show_string(0, 3, "Sensor Ready", FONT8X16);
402	  usleep(1000000);
403	
404	  /* Main loop */
405	
406	  printf("\n[SENSOR] Starting sensor loop (every %d sec)...\n\n",
407	         SENSOR_INTERVAL_SEC);
408	
409	  while (loop_count < 30)
