1	/****************************************************************************
2	 * assets/i2c_light_sensor_template.c
3	 *
4	 * I2C 光照传感器驱动模板（以 BH1750 为范例）
5	 *
6	 * Hummingbird 2K300 板 I2C1 引脚：
7	 *   - I2C1_SDA: GPIO50 (MAIN_FUNC)
8	 *   - I2C1_SCL: GPIO51 (MAIN_FUNC)
9	 *
10	 * 使用说明：
11	 *   1. 引脚复用在 ls2k300_bringup.c 中已配置
12	 *   2. 根据传感器 datasheet 调整命令和读取流程
13	 ****************************************************************************/
14	
15	#include <nuttx/config.h>
16	#include <sys/ioctl.h>
17	#include <stdio.h>
18	#include <fcntl.h>
19	#include <string.h>
20	#include <unistd.h>
21	#include <stdint.h>
22	
23	#include <nuttx/i2c/i2c_master.h>
24	#include <nuttx/arch.h>
25	
26	/* 已配置为 Hummingbird 2K300 板实际值 */
27	
28	#define I2C_BUS         "/dev/i2c1"         /* I2C1 总线，GPIO50(SDA)/GPIO51(SCL) */
29	#define SLAVE_ADDR      0x23                /* BH1750 默认 7-bit 地址 */
30	
31	/* BH1750 命令定义 */
32	
33	#define BH1750_POWER_ON     0x01
34	#define BH1750_RESET        0x07
35	#define BH1750_CONT_HRES    0x10    /* 连续高分辨率模式 */
36	#define BH1750_CONT_HRES2   0x11    /* 连续高分辨率模式2 */
37	#define BH1750_CONT_LRES    0x13    /* 连续低分辨率模式 */
38	#define BH1750_ONE_HRES     0x20    /* 单次高分辨率模式 */
39	#define BH1750_ONE_HRES2    0x21    /* 单次高分辨率模式2 */
40	#define BH1750_ONE_LRES     0x23    /* 单次低分辨率模式 */
41	
42	/* 测量等待时间（毫秒） */
43	
44	#define BH1750_HRES_WAIT_MS  180
45	#define BH1750_LRES_WAIT_MS  24
46	
47	static int g_i2c_fd = -1;
48	
49	/****************************************************************************
50	 * Name: i2c_write_cmd
51	 *
52	 * Description:
53	 *   向 I2C 设备写入单字节命令。
54	 ****************************************************************************/
55	
56	static int i2c_write_cmd(uint8_t cmd)
57	{
58	  struct i2c_msg_s msg;
59	  struct i2c_transfer_s xfer;
60	
61	  msg.addr   = SLAVE_ADDR;
62	  msg.flags  = 0;           /* 写操作 */
63	  msg.buffer = &cmd;
64	  msg.length = 1;
65	
66	  xfer.msgv = &msg;
67	  xfer.msgc = 1;
68	
69	  return ioctl(g_i2c_fd, I2CIOC_TRANSFER, &xfer);
70	}
71	
72	/****************************************************************************
73	 * Name: i2c_read_bytes
74	 *
75	 * Description:
76	 *   从 I2C 设备读取指定长度数据。
77	 ****************************************************************************/
78	
79	static int i2c_read_bytes(uint8_t *buf, uint8_t len)
80	{
81	  struct i2c_msg_s msg;
82	  struct i2c_transfer_s xfer;
83	
84	  msg.addr   = SLAVE_ADDR;
85	  msg.flags  = I2C_M_READ;
86	  msg.buffer = buf;
87	  msg.length = len;
88	
89	  xfer.msgv = &msg;
90	  xfer.msgc = 1;
91	
92	  return ioctl(g_i2c_fd, I2CIOC_TRANSFER, &xfer);
93	}
94	
95	/****************************************************************************
96	 * Name: light_sensor_init
97	 *
98	 * Description:
99	 *   初始化光照传感器。
100	 ****************************************************************************/
101	
102	int light_sensor_init(void)
103	{
104	  int ret;
105	
106	  g_i2c_fd = open(I2C_BUS, O_RDWR);
107	  if (g_i2c_fd < 0)
108	    {
109	      printf("[LIGHT] ERROR: open %s: %d\n", I2C_BUS, errno);
110	      return -errno;
111	    }
112	
113	  /* 上电 */
114	
115	  ret = i2c_write_cmd(BH1750_POWER_ON);
116	  if (ret < 0)
117	    {
118	      printf("[LIGHT] ERROR: power on: %d\n", ret);
119	      return ret;
120	    }
121	
122	  /* 重置 */
123	
124	  ret = i2c_write_cmd(BH1750_RESET);
125	  if (ret < 0)
126	    {
127	      printf("[LIGHT] ERROR: reset: %d\n", ret);
128	      return ret;
129	    }
130	
131	  up_mdelay(10);
132	
133	  printf("[LIGHT] BH1750 init done, addr=0x%02x\n", SLAVE_ADDR);
134	  return 0;
135	}
136	
137	/****************************************************************************
138	 * Name: light_sensor_read_once
139	 *
140	 * Description:
141	 *   单次测量模式读取光照强度。
142	 *
143	 * Output Parameters:
144	 *   lux - 光照强度（单位：lux）
145	 *
146	 * Returned Value:
147	 *   0 on success, negative errno on failure.
148	 ****************************************************************************/
149	
150	int light_sensor_read_once(uint16_t *lux)
151	{
152	  uint8_t buf[2];
153	  int ret;
154	  uint16_t raw;
155	
156	  /* 发送单次高分辨率测量命令 */
157	
158	  ret = i2c_write_cmd(BH1750_ONE_HRES);
159	  if (ret < 0)
160	    {
161	      return ret;
162	    }
163	
164	  /* 等待测量完成 */
165	
166	  up_mdelay(BH1750_HRES_WAIT_MS);
167	
168	  /* 读取 2 字节结果 */
169	
170	  ret = i2c_read_bytes(buf, 2);
171	  if (ret < 0)
172	    {
173	      return ret;
174	    }
175	
176	  /* 合并高低字节 */
177	
178	  raw = ((uint16_t)buf[0] << 8) | buf[1];
179	
180	  /* 换算：raw / 1.2 ≈ lux（整数：raw * 10 / 12） */
181	
182	  *lux = (uint16_t)(((uint32_t)raw * 10 + 6) / 12);
183	
184	  return 0;
185	}
186	
187	/****************************************************************************
188	 * Name: light_sensor_start_continuous
189	 *
190	 * Description:
191	 *   启动连续测量模式。
192	 ****************************************************************************/
193	
194	int light_sensor_start_continuous(void)
195	{
196	  return i2c_write_cmd(BH1750_CONT_HRES);
197	}
198	
199	/****************************************************************************
200	 * Name: light_sensor_read_continuous
201	 *
202	 * Description:
203	 *   在连续模式下读取光照强度（不发送测量命令）。
204	 ****************************************************************************/
205	
206	int light_sensor_read_continuous(uint16_t *lux)
207	{
208	  uint8_t buf[2];
209	  int ret;
210	  uint16_t raw;
211	
212	  ret = i2c_read_bytes(buf, 2);
213	  if (ret < 0)
214	    {
215	      return ret;
216	    }
217	
218	  raw = ((uint16_t)buf[0] << 8) | buf[1];
219	  *lux = (uint16_t)(((uint32_t)raw * 10 + 6) / 12);
220	
221	  return 0;
222	}
223	
224	/****************************************************************************
225	 * Name: light_sensor_deinit
226	 ****************************************************************************/
227	
228	void light_sensor_deinit(void)
229	{
230	  if (g_i2c_fd >= 0)
231	    {
232	      i2c_write_cmd(0x00);  /* 断电 */
233	      close(g_i2c_fd);
234	      g_i2c_fd = -1;
235	    }
236	}
