131	
132	static int eeprom_read_byte(uint16_t mem_addr, uint8_t *data)
133	{
134	  uint8_t addr[2];
135	  int ret;
136	
137	  addr[0] = (uint8_t)(mem_addr >> 8);
138	  addr[1] = (uint8_t)(mem_addr & 0xff);
139	
140	  ret = eeprom_i2c_write(EEPROM_ADDR, addr, 2);
141	  if (ret < 0)
142	    {
143	      return ret;
144	    }
145	
146	  return eeprom_i2c_read(EEPROM_ADDR, data, 1);
147	}
148	
149	static int eeprom_write_byte(uint16_t mem_addr, uint8_t data)
150	{
151	  uint8_t buf[3];
152	
153	  buf[0] = (uint8_t)(mem_addr >> 8);
154	  buf[1] = (uint8_t)(mem_addr & 0xff);
155	  buf[2] = data;
156	
157	  return eeprom_i2c_write(EEPROM_ADDR, buf, 3);
158	}
159	
160	static int eeprom_write_page(uint16_t mem_addr,
161	                             const uint8_t *data, int len)
162	{
163	  uint8_t buf[2 + EEPROM_PAGE_SIZE];
164	  int i;
165	
166	  if (len > EEPROM_PAGE_SIZE)
167	    {
168	      len = EEPROM_PAGE_SIZE;
169	    }
170	
171	  buf[0] = (uint8_t)(mem_addr >> 8);
172	  buf[1] = (uint8_t)(mem_addr & 0xff);
173	  for (i = 0; i < len; i++)
174	    {
175	      buf[2 + i] = data[i];
176	    }
177	
178	  return eeprom_i2c_write(EEPROM_ADDR, buf, 2 + len);
179	}
180	
181	static int eeprom_read_bytes(uint16_t mem_addr,
182	                             uint8_t *data, int len)
183	{
184	  uint8_t addr[2];
185	  int ret;
186	
187	  addr[0] = (uint8_t)(mem_addr >> 8);
188	  addr[1] = (uint8_t)(mem_addr & 0xff);
189	
190	  ret = eeprom_i2c_write(EEPROM_ADDR, addr, 2);
191	  if (ret < 0)
192	    {
193	      return ret;
194	    }
195	
196	  return eeprom_i2c_read(EEPROM_ADDR, data, len);
197	}
