199	static void eeprom_print_contents(void)
200	{
201	  uint8_t magic;
202	  uint8_t count;
203	  uint8_t i;
204	  int ret;
205	
206	  printf("[EEPROM] ---- Current EEPROM Contents ----\n");
207	
208	  ret = eeprom_read_byte(EEPROM_MAGIC_ADDR, &magic);
209	  if (ret < 0)
210	    {
211	      printf("[EEPROM] ERROR: read magic failed: %d\n", ret);
212	      return;
213	    }
214	
215	  printf("[EEPROM] Magic: 0x%02X (%s)\n",
216	         magic, (magic == EEPROM_MAGIC_VALUE) ? "valid" : "invalid");
217	
218	  if (magic != EEPROM_MAGIC_VALUE)
219	    {
220	      printf("[EEPROM] No valid data stored\n");
221	      printf("[EEPROM] ---- End of EEPROM ----\n\n");
222	      return;
223	    }
224	
225	  ret = eeprom_read_byte(EEPROM_COUNT_ADDR, &count);
226	  if (ret < 0)
227	    {
228	      printf("[EEPROM] ERROR: read count failed: %d\n", ret);
229	      return;
230	    }
231	
232	  printf("[EEPROM] Stored readings: %u\n", count);
233	
234	  if (count > EEPROM_MAX_READINGS)
235	    {
236	      count = EEPROM_MAX_READINGS;
237	    }
238	
239	  for (i = 0; i < count; i++)
240	    {
241	      uint8_t buf[2];
242	      uint16_t lux_x100;
243	
244	      ret = eeprom_read_bytes(EEPROM_DATA_ADDR + i * 2, buf, 2);
245	      if (ret < 0)
246	        {
247	          printf("[EEPROM]   [%u] read error: %d\n", i, ret);
248	          continue;
249	        }
250	
251	      lux_x100 = ((uint16_t)buf[0] << 8) | buf[1];
252	      printf("[EEPROM]   [%u] %u.%02u lux\n",
253	             i, lux_x100 / 100, lux_x100 % 100);
254	    }
255	
256	  printf("[EEPROM] ---- End of EEPROM ----\n\n");
257	}
258	
259	static int eeprom_save_readings(const uint16_t *readings, int count)
260	{
261	  uint8_t buf[EEPROM_MAX_READINGS * 2];
262	  int i;
263	  int ret;
264	  int page_off;
265	  int page_len;
266	
267	  if (count > EEPROM_MAX_READINGS)
268	    {
269	      count = EEPROM_MAX_READINGS;
270	    }
271	
272	  /* Pack readings into byte array (big-endian uint16_t) */
273	
274	  for (i = 0; i < count; i++)
275	    {
276	      buf[i * 2]     = (uint8_t)(readings[i] >> 8);
277	      buf[i * 2 + 1] = (uint8_t)(readings[i] & 0xff);
278	    }
279	
280	  /* Write count */
281	
282	  ret = eeprom_write_byte(EEPROM_COUNT_ADDR, (uint8_t)count);
283	  if (ret < 0)
284	    {
285	      printf("[EEPROM] ERROR: write count failed: %d\n", ret);
286	      return ret;
287	    }
288	
289	  usleep(EEPROM_WRITE_DELAY * 1000);
290	
291	  /* Write data in page-sized chunks */
292	
293	  for (page_off = 0; page_off < count * 2; page_off += EEPROM_PAGE_SIZE)
294	    {
295	      page_len = count * 2 - page_off;
296	      if (page_len > EEPROM_PAGE_SIZE)
297	        {
298	          page_len = EEPROM_PAGE_SIZE;
299	        }
300	
301	      ret = eeprom_write_page(EEPROM_DATA_ADDR + page_off,
302	                              &buf[page_off], page_len);
303	      if (ret < 0)
304	        {
305	          printf("[EEPROM] ERROR: write data at 0x%04X failed: %d\n",
306	                 EEPROM_DATA_ADDR + page_off, ret);
307	          return ret;
308	        }
309	
310	      usleep(EEPROM_WRITE_DELAY * 1000);
311	    }
312	
313	  /* Write magic last (signals data is valid) */
314	
315	  ret = eeprom_write_byte(EEPROM_MAGIC_ADDR, EEPROM_MAGIC_VALUE);
316	  if (ret < 0)
317	    {
318	      printf("[EEPROM] ERROR: write magic failed: %d\n", ret);
319	      return ret;
320	    }
321	
322	  usleep(EEPROM_WRITE_DELAY * 1000);
323	
324	  /* Verify */
325	
326	  for (i = 0; i < count; i++)
327	    {
328	      uint8_t verify[2];
329	      uint16_t stored;
330	
331	      ret = eeprom_read_bytes(EEPROM_DATA_ADDR + i * 2, verify, 2);
332	      if (ret < 0)
333	        {
334	          printf("[EEPROM] ERROR: verify read [%d] failed: %d\n", i, ret);
335	          return ret;
336	        }
337	
338	      stored = ((uint16_t)verify[0] << 8) | verify[1];
339	      if (stored != readings[i])
340	        {
341	          printf("[EEPROM] ERROR: verify mismatch [%d]: "
342	                 "expected %u, got %u\n", i, readings[i], stored);
343	          return -EIO;
344	        }
345	    }
346	
347	  printf("[EEPROM] Saved and verified %d readings\n", count);
348	  return OK;
349	}
