360	static int bh1750_init(void)
361	{
362	  int ret;
363	
364	  g_bh1750_addr = BH1750_ADDR_LOW;
365	  ret = bh1750_write_cmd(BH1750_POWER_ON);
366	  if (ret < 0)
367	    {
368	      printf("[BH1750] probe addr 0x%02x failed\n", BH1750_ADDR_LOW);
369	      g_bh1750_addr = BH1750_ADDR_HIGH;
370	      ret = bh1750_write_cmd(BH1750_POWER_ON);
371	    }
372	
373	  if (ret < 0)
374	    {
375	      printf("[BH1750] probe addr 0x%02x failed\n", BH1750_ADDR_HIGH);
376	      printf("[BH1750] no ACK, check wiring\n");
377	      return ret;
378	    }
379	
380	  printf("[BH1750] detected addr=0x%02x\n", g_bh1750_addr);
381	  usleep(20000);
382	
383	  ret = bh1750_write_cmd(BH1750_RESET);
384	  if (ret < 0)
385	    {
386	      printf("[BH1750] reset failed\n");
387	      return ret;
388	    }
389	
390	  usleep(20000);
391	
392	  ret = bh1750_write_cmd(BH1750_H_MODE);
393	  if (ret < 0)
394	    {
395	      printf("[BH1750] set H-mode failed\n");
396	      return ret;
397	    }
398	
399	  usleep(BH1750_READ_DELAY * 1000);
400	
401	  printf("[BH1750] init OK\n");
402	  return OK;
403	}
