492	static int read_and_save_light(void)
493	{
494	  uint16_t readings[EEPROM_MAX_READINGS];
495	  int bh1750_ok = 0;
496	  int i;
497	  int ret;
498	
499	  printf("\n[EEPROM] === KEY1 pressed: reading light sensor 5 times ===\n");
500	
501	  /* Initialize BH1750 */
502	
503	  ret = bh1750_init();
504	  if (ret < 0)
505	    {
506	      printf("[EEPROM] BH1750 init failed, aborting\n");
507	      return ret;
508	    }
509	
510	  bh1750_ok = 1;
511	
512	  /* Read 5 times */
513	
514	  for (i = 0; i < EEPROM_MAX_READINGS; i++)
515	    {
516	      usleep(300000);  /* 300ms between readings */
517	
518	      if (bh1750_ok)
519	        {
520	          ret = bh1750_read_lux(&readings[i]);
521	          if (ret < 0)
522	            {
523	              printf("[EEPROM]   [%d] BH1750 read failed: %d\n", i, ret);
524	              readings[i] = 0;
525	              /* Try reinit */
526	
527	              usleep(500000);
528	              bh1750_ok = (bh1750_init() == 0);
529	            }
530	          else
531	            {
532	              printf("[EEPROM]   [%d] light = %u.%02u lux\n",
533	                     i, readings[i] / 100, readings[i] % 100);
534	            }
535	        }
536	      else
537	        {
538	          readings[i] = 0;
539	          printf("[EEPROM]   [%d] sensor unavailable\n", i);
540	        }
541	    }
542	
543	  /* Save to EEPROM */
544	
545	  printf("[EEPROM] Saving readings to EEPROM...\n");
546	  ret = eeprom_save_readings(readings, EEPROM_MAX_READINGS);
547	  if (ret < 0)
548	    {
549	      printf("[EEPROM] Save failed!\n");
550	      return ret;
551	    }
552	
553	  /* Print updated EEPROM contents */
554	
555	  printf("[EEPROM] Verifying EEPROM contents:\n");
556	  eeprom_print_contents();
557	
558	  return OK;
559	}
