34	    IoTGpioInit(PWM_GPIO);
35	
36	    uint32_t ret = IoTPwmInit(PWM_PORT);
37	    printf("[PwmExample] IoTPwmInit ret: %d\r\n", ret);
38	
39	    uint32_t counter  = 0;
40	    uint32_t running = 1;
41	
42	    while (running) {
43	        for (int i = 0; i < 100; i++) {
44	            IoTPwmStart(PWM_PORT, i, Frequency);
45	            osDelay(5);
46	            IoTPwmStop(PWM_PORT);
47	        }
48	        counter++;
49	        if (counter >= 100) {
50	            running = 0;
51	        }
52	    }
53	}
