44	static int ls2k300_pwm_setup(FAR struct pwm_lowerhalf_s *dev)
45	{
46	  FAR struct ls2k300_pwm_priv_s *priv =
47	      (FAR struct ls2k300_pwm_priv_s *)dev;
48	  uint32_t regval;
49	
50	  regval = pwm_getreg(priv, LS2K300_PWM_CTRL);
51	  regval &= ~PWM_CTRL_EN;
52	  pwm_putreg(priv, LS2K300_PWM_CTRL, regval);
53	
54	  regval = pwm_getreg(priv, LS2K300_PWM_CTRL);
55	  regval |= PWM_CTRL_RST;
56	  pwm_putreg(priv, LS2K300_PWM_CTRL, regval);
57	  regval &= ~PWM_CTRL_RST;
58	  pwm_putreg(priv, LS2K300_PWM_CTRL, regval);
59	
60	  priv->initialized = true;
61	  return OK;
62	}
