64	static int ls2k300_pwm_shutdown(FAR struct pwm_lowerhalf_s *dev)
65	{
66	  FAR struct ls2k300_pwm_priv_s *priv =
67	      (FAR struct ls2k300_pwm_priv_s *)dev;
68	  uint32_t regval;
69	
70	  pwm_putreg(priv, LS2K300_PWM_LOW_BUFFER, 1);
71	  if (!priv->full_buffer)
72	    {
73	      pwm_putreg(priv, LS2K300_PWM_FULL_BUFFER, 10000);
74	    }
75	
76	  regval = pwm_getreg(priv, LS2K300_PWM_CTRL);
77	  regval |= PWM_CTRL_RST;
78	  pwm_putreg(priv, LS2K300_PWM_CTRL, regval);
79	  regval &= ~PWM_CTRL_RST;
80	  pwm_putreg(priv, LS2K300_PWM_CTRL, regval);
81	
82	  regval = pwm_getreg(priv, LS2K300_PWM_CTRL);
83	  regval &= ~PWM_CTRL_EN;
84	  pwm_putreg(priv, LS2K300_PWM_CTRL, regval);
85	
86	  priv->initialized = false;
87	  return OK;
88	}
