90	static int ls2k300_pwm_start(FAR struct pwm_lowerhalf_s *dev,
91	                             FAR const struct pwm_info_s *info)
92	{
93	  FAR struct ls2k300_pwm_priv_s *priv =
94	      (FAR struct ls2k300_pwm_priv_s *)dev;
95	  uint32_t regval;
96	  uint64_t val;
97	
98	  val = (uint64_t)priv->clock_freq * info->frequency;
99	  val = val / 1000000UL;
100	  if (val < 1)
101	    {
102	      val = 1;
103	    }
104	
105	  priv->full_buffer = (uint32_t)val;
106	
107	  val = (uint64_t)priv->full_buffer * (uint64_t)info->duty;
108	  val = val / 65536UL;
109	  if (val < 1)
110	    {
111	      val = 1;
112	    }
113	
114	  priv->low_buffer = (uint32_t)val;
115	
116	  pwm_putreg(priv, LS2K300_PWM_LOW_BUFFER, priv->low_buffer);
117	  pwm_putreg(priv, LS2K300_PWM_FULL_BUFFER, priv->full_buffer);
118	
119	  regval = pwm_getreg(priv, LS2K300_PWM_CTRL);
120	  regval |= PWM_CTRL_EN | PWM_CTRL_OE;
121	  pwm_putreg(priv, LS2K300_PWM_CTRL, regval);
122	
123	  return OK;
124	}
125	
126	static int ls2k300_pwm_stop(FAR struct pwm_lowerhalf_s *dev)
127	{
128	  FAR struct ls2k300_pwm_priv_s *priv =
129	      (FAR struct ls2k300_pwm_priv_s *)dev;
130	  uint32_t regval;
131	
132	  pwm_putreg(priv, LS2K300_PWM_LOW_BUFFER, 1);
133	  if (!priv->full_buffer)
134	    {
135	      pwm_putreg(priv, LS2K300_PWM_FULL_BUFFER, 10000);
136	    }
137	
138	  regval = pwm_getreg(priv, LS2K300_PWM_CTRL);
139	  regval |= PWM_CTRL_RST;
140	  pwm_putreg(priv, LS2K300_PWM_CTRL, regval);
141	  regval &= ~PWM_CTRL_RST;
142	  pwm_putreg(priv, LS2K300_PWM_CTRL, regval);
143	
144	  regval = pwm_getreg(priv, LS2K300_PWM_CTRL);
145	  regval &= ~PWM_CTRL_EN;
146	  pwm_putreg(priv, LS2K300_PWM_CTRL, regval);
147	
148	  return OK;
149	}
150	
151	static int ls2k300_pwm_ioctl(FAR struct pwm_lowerhalf_s *dev,
152	                             int cmd, unsigned long arg)
153	{
154	  FAR struct ls2k300_pwm_priv_s *priv =
155	      (FAR struct ls2k300_pwm_priv_s *)dev;
156	  uint32_t regval;
157	
158	  switch (cmd)
159	    {
160	      case PWMIOC_START:
161	        return ls2k300_pwm_start(dev, (FAR const struct pwm_info_s *)arg);
162	
163	      case PWMIOC_STOP:
164	        return ls2k300_pwm_stop(dev);
165	
166	      default:
167	        break;
168	    }
169	
170	  switch (cmd)
171	    {
172	      case 0x2001:
173	        regval = pwm_getreg(priv, LS2K300_PWM_CTRL);
174	        regval |= PWM_CTRL_INVERT;
175	        pwm_putreg(priv, LS2K300_PWM_CTRL, regval);
176	        break;
177	
178	      case 0x2002:
179	        regval = pwm_getreg(priv, LS2K300_PWM_CTRL);
180	        regval &= ~PWM_CTRL_INVERT;
181	        pwm_putreg(priv, LS2K300_PWM_CTRL, regval);
182	        break;
183	
184	      default:
185	        return -ENOTTY;
186	    }
187	
188	  return OK;
189	}
