26	  int ret;
27	  char path[32];
28	  int i;
29	  int j;
30	  int ok = 0;
31	
32	  printf("[LED] Testing %d LEDs (active-low)...\n", LED_COUNT);
33	
34	  /* Initialize all LEDs */
35	
36	  for (i = 0; i < LED_COUNT; i++)
