/* LS2K300 Mini DP board: GPIO 86 is PWM output (second function) */
#define PWM_GPIO 86
#define PWM_PORT 0
#define Frequency 1230

static void PwmTask(void *arg)
{
    (void) arg;

    ls_pinmux_pin_setup(PWM_GPIO, LS_PINMUX_MODE_AS_SECOND_FUNC);
    IoTGpioInit(PWM_GPIO);

    uint32_t ret = IoTPwmInit(PWM_PORT);
    printf("[PwmExample] IoTPwmInit ret: %d\r\n", ret);

    uint32_t counter  = 0;
    uint32_t running = 1;

    while (running) {
        for (int i = 0; i < 100; i++) {
            IoTPwmStart(PWM_PORT, i, Frequency);
            osDelay(5);
            IoTPwmStop(PWM_PORT);
        }
        counter++;
        if (counter >= 100) {
            running = 0;
        }
    }
}

static void PwmEntry(void)
{
    osThreadAttr_t attr;
    attr.name = "PwmTask";
    attr.stack_size = 2048;
    attr.priority = osPriorityNormal;
    attr.attr_bits = 0U;
    attr.cb_mem = NULL;
    attr.cb_size = 0U;
    attr.stack_mem = NULL;

    if (osThreadNew(PwmTask, NULL, &attr) == NULL) {
        printf("[PwmExample] Falied to create PwmTask!\n");
    }
}

