#include "cmsis_os2.h"
#include "iot_gpio.h"
#include "los_tick.h"
#include "ohos_init.h"
#include "pinmux.h"

#define SERVO_TASK_STACK_SIZE 2048
#define SERVO_TASK_PRIORITY   osPriorityNormal
#define SERVO_PERIOD_US       20000
#define SERVO_STOP_PULSE_US   1500
#define SERVO_FORWARD_PULSE_US 1800
#define SERVO_REVERSE_PULSE_US 1200
#define SERVO_HALF_TURN_CYCLES 25
#define SERVO_STOP_CYCLES      50

#define BLUE_LED_GPIO          88
#define BREATH_LED_GPIO        72
#define BREATH_TASK_STACK_SIZE 2048
#define BREATH_TASK_PRIORITY   osPriorityNormal
#define BREATH_PWM_PERIOD_US   2000
#define BREATH_STEP_PERCENT    2
#define BREATH_STEP_CYCLES     6

/*
 * LOONG-HAT Servo Connector signals are routed through the 40-pin header:
 * HAT GPIO11 -> 40-pin 38 -> LS2K300 GPIO62
 * HAT GPIO6  -> 40-pin 40 -> LS2K300 GPIO60
 * HAT GPIO61 -> 40-pin 15 -> LS2K300 GPIO81
 * HAT GPIO63 -> 40-pin 16 -> LS2K300 GPIO70
 */
static const unsigned int g_servoGpios[] = {
    62,
    60,
    81,
    70,
};

static void BlueLedInit(void)
{
    (void)ls_pinmux_pin_setup(BLUE_LED_GPIO, LS_PINMUX_MODE_AS_GPIO);
    (void)IoTGpioInit(BLUE_LED_GPIO);
    (void)IoTGpioSetDir(BLUE_LED_GPIO, IOT_GPIO_DIR_OUT);
    (void)IoTGpioSetOutputVal(BLUE_LED_GPIO, IOT_GPIO_VALUE1);
}

static void BreathLedInit(void)
{
    (void)ls_pinmux_pin_setup(BREATH_LED_GPIO, LS_PINMUX_MODE_AS_GPIO);
    (void)IoTGpioInit(BREATH_LED_GPIO);
    (void)IoTGpioSetDir(BREATH_LED_GPIO, IOT_GPIO_DIR_OUT);
    (void)IoTGpioSetOutputVal(BREATH_LED_GPIO, IOT_GPIO_VALUE0);
}

static void TaskYield(void)
{
    (void)osThreadYield();
}

static void BreathLedOutputDuty(uint32_t dutyPercent)
{
    uint32_t highUs;

    if (dutyPercent == 0) {
        (void)IoTGpioSetOutputVal(BREATH_LED_GPIO, IOT_GPIO_VALUE0);
        LOS_UDelay(BREATH_PWM_PERIOD_US);
        TaskYield();
        return;
    }

    if (dutyPercent >= 100) {
        (void)IoTGpioSetOutputVal(BREATH_LED_GPIO, IOT_GPIO_VALUE1);
        LOS_UDelay(BREATH_PWM_PERIOD_US);
        TaskYield();
        return;
    }

    highUs = (BREATH_PWM_PERIOD_US * dutyPercent) / 100;
    (void)IoTGpioSetOutputVal(BREATH_LED_GPIO, IOT_GPIO_VALUE1);
    LOS_UDelay(highUs);
    (void)IoTGpioSetOutputVal(BREATH_LED_GPIO, IOT_GPIO_VALUE0);
    LOS_UDelay(BREATH_PWM_PERIOD_US - highUs);
    TaskYield();
}

static void BreathLedHoldDuty(uint32_t dutyPercent)
{
    for (uint32_t i = 0; i < BREATH_STEP_CYCLES; i++) {
        BreathLedOutputDuty(dutyPercent);
    }
}

static void BreathLedTask(void *arg)
{
    (void)arg;

    printf("[LOONG-HAT-PWM] breath LED GPIO%d software PWM start\r\n", BREATH_LED_GPIO);
    BreathLedInit();

    while (1) {
        for (uint32_t duty = 0; duty <= 100; duty += BREATH_STEP_PERCENT) {
            BreathLedHoldDuty(duty);
        }

        for (uint32_t duty = 100; duty > 0; duty -= BREATH_STEP_PERCENT) {
            BreathLedHoldDuty(duty);
        }
    }
}

static void ServoGpioInit(void)
{
    for (uint32_t i = 0; i < sizeof(g_servoGpios) / sizeof(g_servoGpios[0]); i++) {
        (void)ls_pinmux_pin_setup(g_servoGpios[i], LS_PINMUX_MODE_AS_GPIO);
        (void)IoTGpioInit(g_servoGpios[i]);
        (void)IoTGpioSetDir(g_servoGpios[i], IOT_GPIO_DIR_OUT);
        (void)IoTGpioSetOutputVal(g_servoGpios[i], IOT_GPIO_VALUE0);
    }
}

static void ServoSetOutput(IotGpioValue value)
{
    for (uint32_t i = 0; i < sizeof(g_servoGpios) / sizeof(g_servoGpios[0]); i++) {
        (void)IoTGpioSetOutputVal(g_servoGpios[i], value);
    }
}

static void ServoOutputPulse(uint16_t pulseUs)
{
    ServoSetOutput(IOT_GPIO_VALUE1);
    LOS_UDelay(pulseUs);
    ServoSetOutput(IOT_GPIO_VALUE0);
    LOS_UDelay(SERVO_PERIOD_US - pulseUs);
    TaskYield();
}

static void ServoHoldPulse(uint16_t pulseUs, uint32_t cycles)
{
    printf("[LOONG-HAT-PWM] servo pulse %uus\r\n", pulseUs);

    for (uint32_t i = 0; i < cycles; i++) {
        ServoOutputPulse(pulseUs);
    }
}

static void ServoTask(void *arg)
{
    (void)arg;

    printf("[LOONG-HAT-PWM] servo loop demo start\r\n");
    printf("[LOONG-HAT-PWM] blue LED GPIO%d power indicator on\r\n", BLUE_LED_GPIO);
    printf("[LOONG-HAT-PWM] servo connector LS GPIO: %u/%u/%u/%u\r\n",
        g_servoGpios[0], g_servoGpios[1], g_servoGpios[2], g_servoGpios[3]);

    BlueLedInit();
    ServoGpioInit();

    while (1) {
        ServoHoldPulse(SERVO_FORWARD_PULSE_US, SERVO_HALF_TURN_CYCLES);
        ServoHoldPulse(SERVO_STOP_PULSE_US, SERVO_STOP_CYCLES);
        ServoHoldPulse(SERVO_REVERSE_PULSE_US, SERVO_HALF_TURN_CYCLES);
        ServoHoldPulse(SERVO_STOP_PULSE_US, SERVO_STOP_CYCLES);
    }
}

static void ServoEntry(void)
{
    osThreadAttr_t servoAttr = {
        .name = "ServoTask",
        .attr_bits = 0U,
        .cb_mem = NULL,
        .cb_size = 0U,
        .stack_mem = NULL,
        .stack_size = SERVO_TASK_STACK_SIZE,
        .priority = SERVO_TASK_PRIORITY,
    };
    osThreadAttr_t breathAttr = {
        .name = "BreathLedTask",
        .attr_bits = 0U,
        .cb_mem = NULL,
        .cb_size = 0U,
        .stack_mem = NULL,
        .stack_size = BREATH_TASK_STACK_SIZE,
        .priority = BREATH_TASK_PRIORITY,
    };

    if (osThreadNew(ServoTask, NULL, &servoAttr) == NULL) {
        printf("[LOONG-HAT-PWM] create servo task failed\r\n");
    }

    if (osThreadNew(BreathLedTask, NULL, &breathAttr) == NULL) {
        printf("[LOONG-HAT-PWM] create breath LED task failed\r\n");
    }
}

SYS_RUN(ServoEntry);

