#ifndef PWM_H
#define PWM_H

#include <stdint.h>

#define EXIT_SUCCESS 0
#define EXIT_FAILURE 1

#define SECOND_TO_NS 1000000000 // 1秒的纳秒数


// 硬件pwm工作模式
enum
{
	PWM_MODE_NORMAL = 0, // 正常模式--连续输出pwm波形
	PWM_MODE_PULSE       // 单脉冲模式，每次调用只发送一个脉冲，调用间隔必须大于pwm周期
};

//输出翻转使能
enum
{
	PWM_POLARITY_NORMAL = 0, // 高电平为有效电平，周期开始时，高电平开始
	PWM_POLARITY_INVERT		 // 低电平为有效电平，周期开始时，低电平开始
};

//防死区功能使能
enum
{
	PWM_DZONE_DISABLE = 0,
	PWM_DZONE_ENABLE
};


// 硬件pwm初始化信息
typedef struct
{
	uint8_t *base;                         // PWMn所在的内存地址
	uint8_t mode;						  // 工作模式(单脉冲、连续脉冲)
	uint8_t invert;						  // 输出翻转使能
	uint8_t dzone;						  // 防死区功能使能
	unsigned long period_ns;              // pwm周期(单位ns)
	unsigned long duty_ns;                // pwm低电平输出时间（单位ns）从周期开始算
} pwm_info_type_def;


uint32_t pwm_init(uint8_t port);
uint32_t pwm_deinit(uint8_t port);
uint32_t pwm_start(uint8_t port, uint16_t duty, uint32_t freq);
uint32_t pwm_stop(uint8_t port);

#endif

